fn bin_search(a: &[i32], k: i32) -> bool {
    if a.is_empty() {
        return false;
    }
    
    let mut left: usize = 0;
    let mut right: usize = a.len() - 1;
    
    while left <= right {
        let mid = left + (right - left) / 2;
        
        if a[mid] == k {
            return true;
        } else if a[mid] < k {
            left = mid + 1;
        } else {
            if mid == 0 {
                break;
            }
            right = mid - 1;
        }
    }
    
    false
}